import socket
from typing import List, Dict

def scan_ports(host: str, ports: List[int]) -> Dict[int, bool]:
    results = {}
    for port in ports:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(0.5)
            try:
                s.connect((host, port))
                results[port] = True
            except (socket.timeout, ConnectionRefusedError, OSError):
                results[port] = False
    return results
