import hashlib

def checksum_file(path: str, algorithm: str = "sha256") -> str:
    """Return the hex digest of the file at *path* using *algorithm*."""
    h = hashlib.new(algorithm)
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()
